import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/badge/badge.js';
import '@awesome.me/webawesome/dist/components/progress-bar/progress-bar.js';
import '@awesome.me/webawesome/dist/components/input/input.js';
import '@awesome.me/webawesome/dist/components/details/details.js';
import { windows, total, time, money, day, now, priceAt, cap, prices, socAssumptions, scenario } from './sample.js';
import { mountCharts } from './charts.js';
import { renderPlan, number } from './plan-view.js';

const card = (title, eyebrow, content, cls = '') => `<section class="panel ${cls}"><header class="panel-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><span class="sample-tag">SAMPLE</span></header>${content}</section>`;
const metric = (label, value, note) => `<div class="metric"><div class="muted">${label}</div><strong>${value}</strong><div class="muted">${note}</div></div>`;
const summary = total(windows);
const low = prices.reduce((a, b) => a.cents < b.cents ? a : b);
const high = prices.reduce((a, b) => a.cents > b.cents ? a : b);
const activeMinutes = windows.reduce((sum, w) => sum + (w.end - w.start) * 60, 0);
const planDetails = renderPlan(windows, socAssumptions);
const finalSoc = windows.at(-1)?.projectedSoc;
const targetNote = Number.isFinite(finalSoc) && finalSoc >= 0 && finalSoc <= 100 ? `Projected final SOC: ${number(finalSoc, 1, '%')}; target ${finalSoc < 80 ? 'not reached' : 'reached'} in this sample.` : 'Target feasibility is unknown because the SOC projection is unavailable.';
// Original inline geometric icon; no remote icon resolver.
const icon = '<svg aria-hidden="true" viewBox="0 0 24 24" width="17" height="17"><path d="M13 2 5 13h6l-1 9 9-12h-6z" fill="currentColor"/></svg>';
const priceCard = (mode, title) => card(`Prices & plan · ${title}`, 'CHART COMPARISON', `<div class="chart-intro"><div><strong>${icon} ${mode === 'bar' ? 'A · Interval bars' : 'B · Stepped area'}</strong><p>Same fictional, unverified 15-minute sample · EUR c/kWh, illustrative variable cost including fees and taxes</p></div><div class="chart-actions"><wa-button data-zoom="${mode}" size="small" aria-label="Zoom in ${title}">Zoom +</wa-button><wa-button data-reset="${mode}" size="small" aria-label="Reset ${title} overview">Full horizon</wa-button><span>Wheel zooms · scroll outside chart</span></div></div><div class="price-context"><span>Now <b>${number(priceAt(now)?.cents, 2)} c/kWh</b></span><span>Next window starts at <b>${number(scenario === 'missing' ? null : priceAt(windows[0]?.start)?.cents, 2)} c/kWh</b></span><span>Horizon low <b>${low.cents.toFixed(2)} c/kWh</b> · ${day(low.start)} ${time(low.start)}</span><span>Horizon high <b>${high.cents.toFixed(2)} c/kWh</b> · ${day(high.start)} ${time(high.start)}</span></div><div id="price-${mode}" class="chart price-chart" role="img" aria-label="Fictional price intervals, proposed windows, soft cap, now and ready-by markers"></div><p class="legend">Illustrative sample price bands: <span class="band-green">●</span> ≤30 <span class="band-amber">●</span> &gt;30–45 <span class="band-orange">●</span> &gt;45–60 <span class="band-red">●</span> &gt;60 c/kWh <span class="shade"></span> Proposed window · dashed outline <span class="cap-key"></span> Soft cap ${cap} c/kWh <span class="now-key">│</span> Now</p><p class="subtext">Pins show complete-horizon low/high prices; pins disappear when offscreen. Illustrative sample price bands only, not universal cheap/high thresholds. Below cap is not necessarily a proposed window. The hand-authored plan is not an optimized result. Quarter-hour fluctuations are synthetic around the reference hourly values, not verified market prices. Fixed example dates: 08 Nov yesterday, 09 Nov today, 10 Nov future; no timezone/DST model.</p>${planDetails}`, `prices prices-${mode}`);
document.querySelector('#app').innerHTML = `
<div class="shell"><header class="masthead"><div><div class="brand">SPOTNAV <span>ENHANCED</span></div><h1>Charging, in focus.</h1><p>A single view of your vehicle, plan and charger.</p></div><div class="sample-banner">DESIGN PROTOTYPE · SAMPLE DATA<br><span>Offline illustration — no charger connection</span></div></header>
<div class="alert" role="status"><div><strong>Schedule needs attention</strong><p>Sample charger limits differ from the last sent plan. Charging cannot be confirmed from that response.</p></div><a href="#details">View details ↓</a></div>
<div class="dashboard">
${card('Your vehicle', 'OVERVIEW', `<div class="vehicle-top"><div><div class="status-line"><span class="dot"></span> Connected · waiting to charge</div><div class="soc">48<span>%</span></div><p class="muted">Sample battery level</p></div><div class="target">Target <strong>80%</strong><span>Minimum 40% · by 07:00</span></div></div><wa-progress-bar value="48" aria-label="Sample battery level 48 percent"></wa-progress-bar><p class="waiting">Waiting for the first lower-price window. This is a proposal, not a guarantee of charging.</p><div class="metrics">${metric('Measured now','0.0 kW','Sample reading, not unavailable')}<div class="metric next-metric"><div class="muted">Next proposed window</div><button type="button" id="open-plan" aria-haspopup="dialog">${time(windows[0].start)}–${time(windows[0].end)} <span aria-hidden="true">↗</span></button><div class="muted">${day(windows[0].start)} · view complete plan</div></div>${metric('Active charging',`${activeMinutes} min`,'Estimated plan time')}${metric('Until deadline','16h 30m','07:00 deadline, not predicted finish')}</div><div class="hint"><b>Minimum already met.</b> ${targetNote} The projection assumptions are shown with the plan.</div>`, 'overview')}
${card('Plan controls', 'SIMULATED SETTINGS', `<p class="subtext">Illustrative inputs only. Changes do not recalculate or save a plan. ${scenario === 'missing' ? 'Missing-data scenario: plan pricing and efficiency are unavailable; the price chart remains the separate complete sample.' : scenario === 'long' ? 'Long-plan scenario: eight sample windows.' : scenario === 'invalid' ? 'Invalid-data scenario: plan energy, cost and efficiency are unavailable.' : ''}</p><div class="fields"><wa-input label="Target SOC (%)" value="80" type="number"></wa-input><wa-input label="Minimum SOC (%)" value="40" type="number"></wa-input><wa-input label="Soft cap (€/kWh)" value="0.35" type="number" step="0.01"></wa-input><wa-input label="Ready by" value="07:00" type="time"></wa-input></div><wa-button variant="brand" disabled>Save plan · unavailable</wa-button><div class="controls-plan">${planDetails}<button type="button" id="open-plan-details" aria-haspopup="dialog">View full window details ↗</button></div>`, 'controls')}
${priceCard('bar', 'Bars')}
${priceCard('step', 'Stepped area')}
${card('Charger health', 'DAILY STATUS', `<div class="health"><strong>Needs attention</strong><p>The sample reported limits do not match the last sent schedule. Check the details before relying on the plan.</p></div><p class="subtext">Autonomous dispatch is unarmed. Neither an accepted response nor reported limits prove physical charging.</p><wa-details id="details" summary="View sample evidence & debug controls"><div class="details-body"><p><b>Proposal:</b> ${windows.length} sample windows proposed; not necessarily sent.</p><p><b>Sent acknowledgement:</b> Accepted; response only.</p><p><b>Effective limits:</b> Sample readback differs from the last sent plan; not a profile inventory.</p><p><b>Measured now:</b> Sample 0.0 kW; separate from limits.</p><div class="actions"><wa-button size="small" disabled>Send · unavailable</wa-button><wa-button size="small" disabled>Refresh · unavailable</wa-button></div></div></wa-details>`, 'morek')}
${card('Recent charging', 'SAMPLE MEASURED HISTORY', `<div class="history-head"><div><strong>Yesterday · 22:00–23:00</strong><p class="subtext">Sample measured power · a gap stays unknown</p></div><wa-badge variant="success" pill>Meter example</wa-badge></div><div id="power-chart" class="chart power" role="img" aria-label="Sample measured charging power in kilowatts, with an unavailable measurement gap"></div><p class="subtext">Sample readings held for at most 15 minutes; the 22:30–22:45 gap is unknown. The steps are a display assumption, not continuous measurements.</p><div class="history-stats">${metric('Meter energy','6.0 kWh','Sample meter-counter difference')}${metric('Estimated cost','€0.48','Sample tariff · 8 c/kWh')}${metric('Sent plan','22:00–23:00','Observed flow during the window; gap prevents full comparison')}</div><div class="missing"><strong>Missing data example</strong><span>Previous session: energy unknown, not 0 kWh. A planned window is not measured history.</span></div>`, 'history')}
${card('Costs & savings', 'THIS CHARGE', `<div class="costs">${metric('Estimated energy',`${number(summary.energy, 2, ' kWh', n => n >= 0)}`,`${windows.length} proposed windows`)}${metric('Estimated cost',money(summary.cost),'EUR · variable price incl. fees & taxes')}${metric('Weighted average',`${number(summary.centsPerKwh, 2, ' c/kWh')}`,'Total cost ÷ energy')}${metric('Historical savings','Unknown','Comparable baseline unavailable')}</div><div class="hint">Estimates are illustrative, not bills or measured energy. Unavailable inputs yield unknown affected totals, never zero.</div>`, 'costs-card')}
</div><dialog id="plan-dialog" aria-labelledby="dialog-title"><div class="dialog-head"><div><div class="eyebrow">SAMPLE ONLY</div><h2 id="dialog-title">Proposed charging plan</h2></div><button id="close-plan" type="button" aria-label="Close proposed plan">✕</button></div><p class="subtext">Hand-authored proposal, not an optimized or sent schedule.</p>${planDetails}</dialog><footer>All data and illustrations are samples · No live data, commands or Home Assistant access · Visual design awaiting approval</footer></div>`;
document.querySelectorAll('.prices .legend').forEach(el => { for (const node of el.childNodes) if (node.nodeType === Node.TEXT_NODE) node.textContent = node.textContent.replace('Proposed window · dashed outline', 'Proposed charging · gradient + pale track'); });
document.querySelectorAll('.prices .subtext').forEach(el => el.append(' Fictional dates are in 2026; hatched gaps mean price unavailable, not zero. Historical and future coverage may be missing.'));
document.querySelector('a[href="#details"]').addEventListener('click', () => { document.querySelector('#details').open = true; });
const dialog = document.querySelector('#plan-dialog');
const openPlan = document.querySelector('#open-plan');
let trigger = openPlan;
document.querySelectorAll('#open-plan, #open-plan-details').forEach(button => button.addEventListener('click', () => { trigger = button; dialog.showModal(); document.querySelector('#close-plan').focus(); }));
document.querySelector('#close-plan').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', event => {
  if (event.target !== dialog) return;
  const r = dialog.getBoundingClientRect();
  if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close();
});
dialog.addEventListener('close', () => trigger.focus());
mountCharts();
